import { useId } from "react";
import { CircleNotch, WarningCircle } from "@phosphor-icons/react";
export function SignalButton({children,variant="primary",loading=false,disabled=false,error=false,type="button",icon:Icon,...props}) {return <button {...props} type={type} className={"ss-button ss-button--"+variant} disabled={disabled||loading} aria-busy={loading||undefined} data-error={!!error}>{loading?<CircleNotch size={16}/>:error?<WarningCircle size={16}/>:Icon?<Icon size={16}/>:null}{children}</button>;}
export function SignalField({label,hint,error,loading,disabled,...props}) {const id=useId();return <label className="ss-control">{label}<input {...props} aria-describedby={id} aria-invalid={!!error} disabled={disabled||loading}/><small id={id} role={error?"alert":undefined}>{error || (loading?"正在加载…":hint)}</small></label>;}
export function SignalSelect({label,options,error,hint,disabled,loading,...props}) {const id=useId();return <label className="ss-control">{label}<select {...props} aria-label={props["aria-label"] ?? label} disabled={disabled||loading} aria-invalid={!!error} aria-describedby={id}>{options.map(o=><option key={o.value} value={o.value} disabled={o.disabled}>{o.label}</option>)}</select><small id={id} role={error?"alert":undefined}>{error||hint}</small></label>;}
export function SignalToggle({label,description,checked,onChange,disabled,loading,error}) {return <label className="ss-check"><input type="checkbox" role="switch" checked={checked} disabled={disabled||loading} onChange={e=>onChange?.(e.target.checked)}/><span>{label}<small>{error||description}</small></span></label>;}
export function SignalPanel({title,eyebrow,action,children}) {return <section className="ss-panel">{title||action?<header><span>{eyebrow?<small>{eyebrow}</small>:null}<h3>{title}</h3></span>{action}</header>:null}{children}</section>;}
export function SignalBadge({children}) {return <span className="ss-badge">{children}</span>;}

