      display: "contents"
    }}><dialog ref={dialogRef} className="ss-drawer" aria-labelledby={id} aria-busy={loading || undefined} onCancel={e => {
        e.preventDefault();
        close();
      }}><header><h2 id={id}>{title}</h2><button type="button" onClick={close} aria-label="关闭详情"><X size={18} aria-hidden="true" /></button></header>{loading ? <p role="status">正在加载详情…</p> : null}{error ? <p role="alert">{error}</p> : null}<div ref={element => { if (element) element.inert = Boolean(loading || disabled); }}>{children}<footer>{actions}</footer></div></dialog></div>, document.body) : null}</>;
}
export function SignalDropdownMenu({
  label = "更多操作",
  items,
  disabled = false
}) {
  const [open, setOpen] = useState(false),
    root = useRef(null),
    trigger = useRef(null),
    id = useId();
  const position = usePopupPosition(root, open);
  const close = (focus = true) => {
    setOpen(false);
    if (focus) trigger.current?.focus();
  };
  useEffect(() => {
    if (!open) return;
    const away = e => {
      if (!root.current?.contains(e.target)) setOpen(false);
    };
    document.addEventListener("pointerdown", away);
    root.current?.querySelector('[role="menuitem"]:not(:disabled)')?.focus();
    return () => document.removeEventListener("pointerdown", away);
  }, [open]);
  const keys = e => {
    const all = [...root.current.querySelectorAll('[role="menuitem"]:not(:disabled)')],
      i = all.indexOf(document.activeElement);
    if (e.key === "Escape") {
      e.preventDefault();
      close();
    } else if (e.key === "Tab") setOpen(false);else if (["ArrowDown", "ArrowUp", "Home", "End"].includes(e.key)) {
      e.preventDefault();
      all[e.key === "Home" ? 0 : e.key === "End" ? all.length - 1 : (i + (e.key === "ArrowDown" ? 1 : -1) + all.length) % all.length]?.focus();
    }
  };
  return <span className="ss-popover-anchor" ref={root}><button type="button" ref={trigger} aria-haspopup="menu" aria-controls={id} aria-expanded={open} disabled={disabled} onClick={() => setOpen(!open)} onKeyDown={e => {
      if (e.key === "ArrowDown") {
        e.preventDefault();
        setOpen(true);
      }
    }}>{label}</button>{open ? <div role="menu" id={id} popover="manual" style={position} className="ss-popup" onKeyDown={keys}>{items.map(item => <button type="button" role="menuitem" key={item.id} disabled={item.disabled} data-danger={item.danger} onClick={() => {
        close();
        item.onSelect?.();
      }}>{item.label}</button>)}</div> : null}</span>;
}
