    button = useRef(null),
    id = useId();
  const position = usePopupPosition(ref, open);
  useEffect(() => {
    if (!open) return;
    const listener = e => {
      if (e.type === "keydown" && e.key === "Escape") {
        setOpen(false);
        button.current?.focus();
      } else if (e.type === "pointerdown" && !ref.current?.contains(e.target)) setOpen(false);
    };
    document.addEventListener("pointerdown", listener);
    document.addEventListener("keydown", listener);
    return () => {
      document.removeEventListener("pointerdown", listener);
      document.removeEventListener("keydown", listener);
    };
  }, [open]);
  return <span className="ss-popover-anchor" ref={ref}><button type="button" ref={button} disabled={disabled} aria-expanded={open} aria-controls={id} onClick={() => setOpen(!open)}>{label}</button>{open ? <section id={id} popover="manual" style={position} className="ss-popup" aria-label={label}>{children}<button type="button" onClick={() => {
        setOpen(false);
        button.current?.focus();
      }}>关闭</button></section> : null}</span>;
}
export function SignalTooltip({
  label,
  children
}) {
  const id = useId(),
    [open, setOpen] = useState(false),
    ref = useRef(null);
  const position = usePopupPosition(ref, open);
  return <span ref={ref} className="ss-popover-anchor" onMouseEnter={() => setOpen(true)} onMouseLeave={() => setOpen(false)}><button type="button" aria-describedby={open ? id : undefined} onFocus={() => setOpen(true)} onBlur={() => setOpen(false)} onKeyDown={e => {
      if (e.key === "Escape") setOpen(false);
    }} onClick={() => setOpen(!open)}>{label}</button>{open ? <span role="tooltip" id={id} popover="manual" style={position} className="ss-popup">{children}</span> : null}</span>;
}

// 使用浏览器 top layer，避免宿主页面的 transform / overflow 截断浮层。
function usePopupPosition(ref, open) {
  const [position, setPosition] = useState({});
  useEffect(() => {
    if (!open) return;
    const popup = ref.current?.querySelector('[popover]');
    popup?.showPopover();
    const update = () => {
      const r = ref.current?.getBoundingClientRect();
      if (!r || !popup) return;
      const box = popup.getBoundingClientRect();
      const left = Math.max(8, Math.min(r.left, innerWidth - box.width - 8));
      const top = Math.max(8, Math.min(r.bottom + 8, innerHeight - box.height - 8));
      setPosition({
        position: "fixed",
        margin: 0,
        inset: "auto",
        left,
        top,
        maxHeight: "calc(100dvh - 16px)",
        overflow: "auto"
      });
    };
    update();
    window.addEventListener("resize", update);
    window.addEventListener("scroll", update, true);
    return () => {
      window.removeEventListener("resize", update);
      window.removeEventListener("scroll", update, true);
      if (popup?.matches(":popover-open")) popup.hidePopover();
    };
  }, [open]);
  return position;
}

export function SignalProgress({
  label,
  value,
  max = 100
}) {
  const limit = Number.isFinite(max) && max > 0 ? max : 100;
  const safe = typeof value === "number" && Number.isFinite(value) ? Math.max(0, Math.min(limit, value)) : undefined;
  return <label className="ss-control">{label}<progress value={safe} max={limit} /><small>{safe === undefined ? "处理中…" : Math.round(safe / limit * 100) + "%"}</small></label>;
}
